// Map uniform random sample to [-1,1]^2
Float sx = 2 * u.x - 1;
Float sy = 2 * u.y - 1;

// Handle degenerate case
if (sx == 0 && sy == 0) {
    return Point2f(0, 0);
}

// Apply concentric mapping
Float theta, r;
if (sx >= -sy) {
    if (sx > sy) {
        // Right triangle
        r = sx;
        if (sy > 0) {
            theta = sy / sx;
        } else {
            theta = 8 + sy / sx;
        }
    } else {
        // Top triangle
        r = sy;
        theta = 2 - sx / sy;
    }
} else {
    if (sx <= sy) {
        // Left triangle
        r = sx;
        if (sy < 0) {
            theta = 4 + sy / sx;
        } else {
            theta = 4 + sy / sx;
        }
    } else {
        // Bottom triangle
        r = sy;
        theta = 6 - sx / sy;
    }
}

theta *= Pi / 4;
return Point2f(r * std::cos(theta), r * std::sin(theta));
